js.text:

function grid$s611Manage(f){
  this.constructor(f);
}
grid$s611Manage.prototype = new DirEvent();
grid$s611Manage.prototype.afterInit = function(renderType){
  var p = this._dir;
  //if (p.options._status == 5) p.find(".toolbar-approve").attr('title', p.msg('approve'))
 // else if (p.options._status == 7) p.find(".toolbar-approve").attr('title', p.msg('undo'))
  //else p.find(".toolbar-approve").attr('title', p.msg('open'));
  //p.find(".toolbar-cancel").css("display", (p.options._status == 5)?"":"none")
  //flink = p.field("so_ct", 0)


}
grid$s611Manage.prototype.beforeButtonGridClick = function (id, gindex,opt) {
  var msg,p = this._dir,g = p.grid(), dt = g.data, items = p.selectedItems(),xstatus = 1;
  flink = p.field("so_ct", 0)
  if(flink.link.indexOf("!") == 0) {
			$.question(msg + iId, $.msg.get("QuestionTitle"), p, function (q, v) {
          q._close();
          if (v)
		  {	
			opt = $.extend({}, opt, {controller: "s621", folder: "Dir", dirViewType: "Dialog", parent: p.options.parent, useDataSet: true, memvars: m2});
			p._close();
		   $.createDir(false, opt);

		  }
        });
  }
  m2.val('id', 'I', iId);
  switch (id) {

    case 'so_ct':
		$.question(msg + iId, $.msg.get("QuestionTitle"), p, function (q, v) {
          q._close();
          if (v)
		  {	
			opt = $.extend({}, opt, {controller: "s621", folder: "Dir", dirViewType: "Dialog", parent: p.options.parent, useDataSet: true, memvars: m2});
			p._close();
		   $.createDir(false, opt);

		  }
        });
      return false;
      break;
    case '20':
      if (fees.count() > 0)
        p.showFilter('messageInput', null, {title: p.msg('inputTitle'), label: p.msg('reason'), allowBlank: false, msgFunction: function (q, v, ctext) {
          q._close();
          if (v){
            p.request('Close', '', [["tblKeys", "T", fees.sqlval()], ['xstatus', 'I', xstatus], ['ly_do_huy', 'C', ctext]], function(pp, d, run){
              if (run) {
                p._refresh();
                p.clearSelectedItems();
              }
            });
          }
        }});
      return false;
      break;
    default:
      break;
  }
  return true;
}

css.text:

.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
